/* Поисковый индекс. Создаётся автоматически скриптом dev/build.py. */
window.ATK_SEARCH = [{"t": "Пример 1. Уравнение 5x + 6 = 2 в Z₇", "u": "examples/m01.html#ex-eq", "p": "Примеры решений, модуль 1", "k": "Пояснение Переносим 6. 5x = 2 − 6 = −4. Зачем: оставить слагаемое с x одно, как в школе. Приводим к остатку. −4 ≡ −4 + 7 = 3, то есть 5x = 3. Зачем: в \\(\\mathbb{Z}_7\\) работаем только с числами 0…6. Находим 5⁻¹. Перебором: 5·3 = 15 ≡ 1, значит 5⁻¹ = 3. Зачем: делить по модулю — это умножать на обрат"}, {"t": "Пример 2. Обратный к 8 по модулю 21", "u": "examples/m01.html#ex-inv", "p": "Примеры решений, модуль 1", "k": "Пояснение Перебирать 20 вариантов долго, поэтому применяем табличный алгоритм Евклида. Каждая новая строка = позапрошлая − q · прошлая, где q — частное от деления позапрошлого остатка на прошлый. В каждой строке выполняется r ≡ x·8 (mod 21). Строка r q x Что произошло старт 21 — 0 21 ≡ 0·8 старт 8"}, {"t": "Пример 3. Вектор ошибки над F₅", "u": "examples/m01.html#ex-err", "p": "Примеры решений, модуль 1", "k": "Пояснение, по образцу примера из лекции 1 «Введение» Передали x = 3140 , приняли y = 0142 . Найти вектор ошибки и число ошибок. e = y − x покоординатно: (0 − 3, 1 − 1, 4 − 4, 2 − 0) = (−3, 0, 0, 2). Приводим по модулю 5: −3 ≡ 2. Получаем e = 2002 . Число ошибок — вес вектора ошибки: ‖e‖ = 2. Это и е"}, {"t": "Пример 4. Декодирование максимального правдоподобия", "u": "examples/m01.html#ex-ml", "p": "Примеры решений, модуль 1", "k": "Курс: пример из лекции 1 «Введение» Двоичный код задан кодированием 00 → 00001, 01 → 01010, 10 → 10111, 11 → 11100. Канал — ДСК(p) с p < 1/2. Принято y = 10101 . Что передавали? Считаем расстояния от y до каждого кодового слова — сравниваем разряды. Кодовое слово x d(y, x) \\(P(y \\mid x) = p^{d}(1-p)"}, {"t": "Пример 5. Параметры кода и декодирование", "u": "examples/m01.html#ex-code", "p": "Примеры решений, модуль 1", "k": "Пояснение Код C = { 00000 , 11100 , 00111 , 11011 }. Найти d, t, s, s′, скорость и декодировать слова 10100 и 10001. Все попарные расстояния (пар 4·3/2 = 6): d(00000, 11100) = 3, d(00000, 00111) = 3, d(00000, 11011) = 4; d(11100, 00111) = 4, d(11100, 11011) = 3, d(00111, 11011) = 3."}, {"t": "Пример 6. Код с повторением: во сколько раз меньше ошибок", "u": "examples/m01.html#ex-rep", "p": "Примеры решений, модуль 1", "k": "Курс: пример из лекции 1 «Введение» Голосование по трём битам ошибается, если испорчены ровно 2 бита (3 способа выбрать какие) или все 3: \\(P_{\\text{ош}} = 3p^2(1-p) + p^3 = 3p^2 - 2p^3\\). При p = 0,01: 3·0,0001 − 2·0,000001 = 0,0003 − 0,000002 = 0,000298. Без кодирования ошибка в бите случается с в"}, {"t": "Пример 7. Объём шара и сколько слов поместится", "u": "examples/m01.html#ex-ball", "p": "Примеры решений, модуль 1", "k": "Пояснение, задел на модуль 4 Шар радиуса 1 в \\(\\mathbb{F}_2^7\\): центр плюс 7 соседей (меняем один из 7 разрядов): |B₁| = 1 + 7 = 8. Если код исправляет 1 ошибку, шары радиуса 1 вокруг кодовых слов не пересекаются. Значит, слов не больше 2⁷ / 8 = 128 / 8 = 16. Код Хемминга (7, 4) на главной содержит"}, {"t": "Остаток a mod n", "u": "glossary.html#g-mod", "p": "Словарь терминов и обозначений", "k": "Число r от 0 до n − 1 такое, что a = q·n + r. Пример: −7 mod 5 = 3. подробнее"}, {"t": "Сравнение по модулю a ≡ b (mod n)", "u": "glossary.html#g-cong", "p": "Словарь терминов и обозначений", "k": "n делит a − b; то же самое: a и b дают одинаковый остаток. подробнее"}, {"t": "Кольцо вычетов ℤₙ", "u": "glossary.html#g-zn", "p": "Словарь терминов и обозначений", "k": "Множество {0, 1, …, n − 1} со сложением и умножением по модулю n. Встречается также запись ℤ/nℤ. подробнее"}, {"t": "Поле", "u": "glossary.html#g-field", "p": "Словарь терминов и обозначений", "k": "Множество с четырьмя действиями арифметики (делить нельзя только на 0) и привычными законами. ℤₙ — поле ⇔ n простое. Строгое определение — в модуле 6. подробнее"}, {"t": "Конечное поле \\(\\mathbb{F}_p,\\ \\mathbb{F}_q\\)", "u": "glossary.html#g-fq", "p": "Словарь терминов и обозначений", "k": "\\(\\mathbb{F}_p = \\mathbb{Z}_p\\) при простом p. \\(\\mathbb{F}_q\\) — поле из q элементов; q обязательно степень простого. 𝔽₄ ≠ ℤ₄. подробнее"}, {"t": "Противоположный элемент −a", "u": "glossary.html#g-neg", "p": "Словарь терминов и обозначений", "k": "Число, дающее с a в сумме 0; в ℤₙ это n − a. В ℤ₂ −1 = 1, поэтому вычитание совпадает со сложением. подробнее"}, {"t": "Обратный элемент a⁻¹", "u": "glossary.html#g-inv", "p": "Словарь терминов и обозначений", "k": "Число, для которого a·a⁻¹ ≡ 1. Существует ⇔ НОД(a, n) = 1. Деление: b / a = b·a⁻¹. подробнее"}, {"t": "Делитель нуля", "u": "glossary.html#g-zerodiv", "p": "Словарь терминов и обозначений", "k": "Ненулевой a, для которого a·b = 0 при некотором ненулевом b. Пример: 2·3 = 0 в ℤ₆. В поле делителей нуля нет. подробнее"}, {"t": "НОД, взаимно простые числа", "u": "glossary.html#g-gcd", "p": "Словарь терминов и обозначений", "k": "Наибольший общий делитель. Числа взаимно просты, если их НОД равен 1. подробнее"}, {"t": "Алгоритм Евклида (расширенный)", "u": "glossary.html#g-euclid", "p": "Словарь терминов и обозначений", "k": "Находит НОД последовательными делениями с остатком и коэффициенты u, v в НОД = u·a + v·n; отсюда обратный элемент. Тот же алгоритм для многочленов декодирует коды БЧХ и Гоппы. подробнее"}, {"t": "Соотношение Безу", "u": "glossary.html#g-bezout", "p": "Словарь терминов и обозначений", "k": "НОД(a, n) = u·a + v·n для некоторых целых u, v. подробнее"}, {"t": "Порядок элемента", "u": "glossary.html#g-order", "p": "Словарь терминов и обозначений", "k": "Наименьшее k ≥ 1, при котором aᵏ = 1. В 𝔽₇ порядок 2 равен 3. Порядок делит p − 1. подробнее"}, {"t": "Примитивный элемент", "u": "glossary.html#g-prim", "p": "Словарь терминов и обозначений", "k": "Элемент, степени которого дают все ненулевые элементы поля; его порядок q − 1. Пример: 3 в 𝔽₇. Часто обозначается α. подробнее"}, {"t": "Малая теорема Ферма", "u": "glossary.html#g-fermat", "p": "Словарь терминов и обозначений", "k": "В 𝔽ₚ для любого a ≠ 0 верно \\(a^{p-1} = 1\\). подробнее"}, {"t": "Пространство векторов \\(\\mathbb{F}_q^n\\)", "u": "glossary.html#g-fqn", "p": "Словарь терминов и обозначений", "k": "Все строки длины n из элементов \\(\\mathbb{F}_q\\), всего \\(q^n\\) штук. Операции покоординатные. Запись 1021 означает (1, 0, 2, 1). подробнее"}, {"t": "Линейная комбинация", "u": "glossary.html#g-lincomb", "p": "Словарь терминов и обозначений", "k": "Выражение \\(c_1v_1 + \\dots + c_mv_m\\) с коэффициентами из поля. подробнее"}, {"t": "Сложение по модулю 2 ⊕", "u": "glossary.html#g-xor", "p": "Словарь терминов и обозначений", "k": "XOR: 0 ⊕ 0 = 1 ⊕ 1 = 0, 0 ⊕ 1 = 1 ⊕ 0 = 1. Для векторов — покоординатно. подробнее"}, {"t": "Двоичный симметричный канал ДСК(p)", "u": "glossary.html#g-bsc", "p": "Словарь терминов и обозначений", "k": "Каждый бит независимо переворачивается с вероятностью p. подробнее"}, {"t": "Вектор ошибки e", "u": "glossary.html#g-err", "p": "Словарь терминов и обозначений", "k": "Разность принятого и отправленного слов: y = x + e. Число ошибок — вес e. подробнее"}, {"t": "Блочный код, кодовое слово", "u": "glossary.html#g-blockcode", "p": "Словарь терминов и обозначений", "k": "Код длины n — подмножество \\(C \\subseteq \\mathbb{F}_q^n\\); его элементы — кодовые слова. При кодировании информационное слово длины k переходит в кодовое длины n. подробнее"}, {"t": "Параметры n, k, M", "u": "glossary.html#g-nkm", "p": "Словарь терминов и обозначений", "k": "n — длина кода, k — длина информационного слова (для линейных кодов — размерность), M — число кодовых слов (мощность). подробнее"}, {"t": "Скорость кода R = k/n", "u": "glossary.html#g-rate", "p": "Словарь терминов и обозначений", "k": "Доля информационных символов среди передаваемых. подробнее"}, {"t": "Систематический код", "u": "glossary.html#g-syst", "p": "Словарь терминов и обозначений", "k": "Кодирование, при котором первые (или последние) k разрядов кодового слова совпадают с информационным словом; остальные n − k разрядов — проверочные. подробнее"}, {"t": "Декодирование максимального правдоподобия", "u": "glossary.html#g-ml", "p": "Словарь терминов и обозначений", "k": "Выбор кодового слова x с наибольшей P(y | x). В ДСК(p) при p < 1/2 — ближайшее к y кодовое слово. подробнее"}, {"t": "Расстояние Хемминга d(x, y)", "u": "glossary.html#g-hd", "p": "Словарь терминов и обозначений", "k": "Число разрядов, в которых x и y различаются. Равно ‖y − x‖. подробнее"}, {"t": "Расстояние Ли ρ(x, y)", "u": "glossary.html#g-lee", "p": "Словарь терминов и обозначений", "k": "Σ|xᵢ − yᵢ| при простом q. При q = 2 совпадает с расстоянием Хемминга, в общем случае d ≤ ρ. подробнее"}, {"t": "Вес ‖x‖", "u": "glossary.html#g-weight", "p": "Словарь терминов и обозначений", "k": "Число ненулевых координат вектора. подробнее"}, {"t": "Метрика", "u": "glossary.html#g-metric", "p": "Словарь терминов и обозначений", "k": "Функция расстояния: симметрична, неотрицательна (0 только для одинаковых), удовлетворяет неравенству треугольника. подробнее"}, {"t": "Шар и сфера \\(B_r(a),\\ S_r(a)\\)", "u": "glossary.html#g-ball", "p": "Словарь терминов и обозначений", "k": "Векторы на расстоянии ≤ r (шар) или ровно r (сфера) от a. \\(|S_r| = \\binom{n}{r}(q-1)^r\\). подробнее"}, {"t": "Булев куб, слой, грань", "u": "glossary.html#g-cube", "p": "Словарь терминов и обозначений", "k": "Булев куб — {0, 1}ⁿ. Слой — векторы одного веса. Грань — векторы с фиксированными n − k разрядами, запись вида ∗0∗10. подробнее"}, {"t": "Кодовое расстояние d(C)", "u": "glossary.html#g-dc", "p": "Словарь терминов и обозначений", "k": "Наименьшее расстояние между двумя различными кодовыми словами. подробнее"}, {"t": "Число исправляемых ошибок t", "u": "glossary.html#g-t", "p": "Словарь терминов и обозначений", "k": "t = ⌊(d − 1)/2⌋. В программе — радиус упаковки кода. подробнее"}, {"t": "Число обнаруживаемых ошибок s, s′", "u": "glossary.html#g-s", "p": "Словарь терминов и обозначений", "k": "s = d − 1 в режиме обнаружения; s′ = ⌈(d − 1)/2⌉ в режиме исправления (s′ = t при нечётном d, t + 1 при чётном). подробнее"}, {"t": "Код с повторением", "u": "glossary.html#g-rep", "p": "Словарь терминов и обозначений", "k": "Каждый символ повторяется n раз; декодирование голосованием. d = n, R = 1/n. подробнее"}, {"t": "Бинарная энтропия H(p)", "u": "glossary.html#g-entropy", "p": "Словарь терминов и обозначений", "k": "H(p) = −p log₂ p − (1 − p) log₂(1 − p). подробнее"}, {"t": "Пропускная способность C(p)", "u": "glossary.html#g-capacity", "p": "Словарь терминов и обозначений", "k": "Для ДСК(p): C(p) = 1 − H(p). Ниже неё можно передавать сколь угодно надёжно, выше — нельзя (теоремы Шеннона). подробнее Такого термина пока нет. Попробуйте другое слово или поиск по сайту."}, {"t": "Шум портит биты. Код их чинит.", "u": "index.html#hero-title", "p": "Код без ошибок — подготовка к экзамену по АТК", "k": "Это сайт для подготовки к экзамену по алгебраической теории кодирования. Объясняем с нуля: от остатков при делении до кодов БЧХ, Рида — Соломона и Гоппы. А вот настоящий код Хемминга: попробуйте его сломать. Начать с модуля 1 Открыть план"}, {"t": "Код Хемминга (7, 4) вживую", "u": "index.html#demo-title", "p": "Код без ошибок — подготовка к экзамену по АТК", "k": "Отправляем 4 бита сообщения 0000 , к ним добавлено 3 проверочных. Нажмите на любой бит в строке «Принято» — это помеха в канале. Отправлено Принято (нажмите, чтобы исказить) После декодера 1 2 3 4 5 6 7 Загрузка… Новое сообщение Убрать помехи"}, {"t": "Где вы остановились", "u": "index.html#continue-title", "p": "Код без ошибок — подготовка к экзамену по АТК", "k": "Начать модуль 1"}, {"t": "Как пользоваться", "u": "index.html#how", "p": "Код без ошибок — подготовка к экзамену по АТК", "k": "Идите по плану. Курс разбит на 12 недельных модулей. В каждом: теория, разобранные примеры, задачи и повторение. Сначала пробуйте сами. В задачах подсказка, ответ и полное решение спрятаны отдельно — открывайте по одному. Тренируйтесь говорить. Экзамен устный, поэтому в разделе «Устный экзамен» есть"}, {"t": "Мой прогресс", "u": "index.html#progress", "p": "Код без ошибок — подготовка к экзамену по АТК", "k": "Прогресс появится здесь, когда включён JavaScript."}, {"t": "Модули", "u": "index.html#modules", "p": "Код без ошибок — подготовка к экзамену по АТК", "k": "Статус модуля меняется на странице «План» . 1 Модуль 1. Арифметика по модулю и введение в коды Теория Примеры Практика Повторение"}, {"t": "Быстрые ссылки", "u": "index.html#quick", "p": "Код без ошибок — подготовка к экзамену по АТК", "k": "Арифметика по модулю Остатки, обратный элемент, поле F p Расстояние Хемминга Вес, шары, кодовое расстояние, t, s, s′ Тренажёры Калькулятор по модулю с алгоритмом Евклида, расстояние, параметры кода 27 вопросов программы Что уже разобрано и как отвечать Словарь Термины и обозначения с короткими поясн"}, {"t": "Что нового", "u": "index.html#news", "p": "Код без ошибок — подготовка к экзамену по АТК", "k": "Версия 0.2.4, 25 октября 2026. Заголовок на главной больше не сдвигается, когда вы ломаете биты в демо кода Хемминга. Поле «Кодовые слова» в тренажёре занимает всю ширину. У перевёрнутой карточки не просвечивает лицевая сторона (было заметно в Firefox). Переходы по «Содержанию» и другим ссылкам внут"}, {"t": "1Модуль 1. Арифметика по модулю и введение в коды", "u": "modules.html#m01", "p": "Модули", "k": "26.10–01.11, вопросы программы: 2 1.1 Арифметика по модулю 1.2 Расстояние Хемминга и параметры кода Теория объяснения с нуля Примеры разборы по шагам Практика задачи с подсказками Повторение конспект, карточки, тест"}, {"t": "2Модуль 2. Линейная алгебра над конечным полем", "u": "modules.html#m02", "p": "Модули", "k": "02.11–08.11, база для следующих тем Метод Гаусса над F₂ и F₃ Ранг, базис, размерность Материалы появятся, когда дойдём до этого модуля."}, {"t": "3Модуль 3. Линейные коды", "u": "modules.html#m03", "p": "Модули", "k": "09.11–15.11, вопросы программы: 3, 4 Матрицы G и H Синдром и стандартное расположение Материалы появятся, когда дойдём до этого модуля."}, {"t": "4Модуль 4. Границы для кодов и коды Хемминга", "u": "modules.html#m04", "p": "Модули", "k": "16.11–22.11, вопросы программы: 5, 6, 7 Хемминг, Синглтон, Варшамов–Гильберт, Грайсмер Коды Хемминга Материалы появятся, когда дойдём до этого модуля."}, {"t": "5Модуль 5. Коды Рида–Маллера", "u": "modules.html#m05", "p": "Модули", "k": "23.11–29.11, вопросы программы: 8, 9, 10 Полином Жегалкина Мажоритарное декодирование, преобразование Мёбиуса Материалы появятся, когда дойдём до этого модуля."}, {"t": "6Модуль 6. Многочлены, группы, кольца", "u": "modules.html#m06", "p": "Модули", "k": "30.11–06.12, вопросы программы: 11, 1 Деление многочленов, НОД Идеалы и факторкольца Материалы появятся, когда дойдём до этого модуля."}, {"t": "7Модуль 7. Конечные поля", "u": "modules.html#m07", "p": "Модули", "k": "07.12–13.12, вопросы программы: 1, 12 Поля F₈, F₉, F₁₆ Минимальные многочлены Материалы появятся, когда дойдём до этого модуля."}, {"t": "8Модуль 8. Циклические коды", "u": "modules.html#m08", "p": "Модули", "k": "14.12–20.12, вопросы программы: 12, 13, 14, 15, 16 g(x), h(x), матрицы Корни, порядок многочлена, CRC Материалы появятся, когда дойдём до этого модуля."}, {"t": "9Модуль 9. Коды БЧХ", "u": "modules.html#m09", "p": "Модули", "k": "21.12–27.12, вопросы программы: 17, 18 Граница БЧХ Алгоритм Питерсона — Горенштейна — Цирлера Материалы появятся, когда дойдём до этого модуля."}, {"t": "10Модуль 10. Сложность алгоритмов: рекурсия и Карацуба", "u": "modules.html#m10", "p": "Модули", "k": "28.12–03.01, вопросы программы: 25 Уравнение T(n) = aT(n/b) + cn Умножение Карацубы Материалы появятся, когда дойдём до этого модуля."}, {"t": "11Модуль 11. Декодирование БЧХ и коды Рида — Соломона", "u": "modules.html#m11", "p": "Модули", "k": "04.01–10.01, вопросы программы: 19, 20, 21 Ключевое уравнение, Форни Евклид и Берлекемп — Месси Материалы появятся, когда дойдём до этого модуля."}, {"t": "12Модуль 12. Каскадные коды, коды Гоппы, ДПФ", "u": "modules.html#m12", "p": "Модули", "k": "11.01–17.01, вопросы программы: 22, 23, 24, 26, 27 Каскадные коды и стирания Гоппа и МакЭлис ДПФ и быстрое деление Материалы появятся, когда дойдём до этого модуля."}, {"t": "Разминка по модулю 1 (блок 1.1)", "u": "oral/index.html#warmup", "p": "Подготовка к устному экзамену", "k": "Этих вопросов нет в программе, но они проверяют базу, без которой не ответить на вопрос 1 о конечных полях. Пояснение Что означает a ≡ b (mod n)? Дайте два равносильных описания. n делит a − b; равносильно: a и b дают одинаковый остаток при делении на n. Почему в двоичных кодах можно не различать сл"}, {"t": "Вопросы программы", "u": "oral/index.html#questions", "p": "Подготовка к устному экзамену", "k": ""}, {"t": "Вопрос 1. Строение конечных полей", "u": "oral/index.html#q1", "p": "Подготовка к устному экзамену", "k": "1. Строение конечных полей впереди: модули 6–7 Строение конечных полей. Неприводимые многочлены. Примитивные элементы и примитивные многочлены, теорема о двучлене \\(x^{p^n} - x\\), сопряжённые элементы поля и минимальный многочлен, подполя в поле \\(\\mathbb{F}_{p^n}\\). Изоморфизм полей одинакового пор"}, {"t": "Вопрос 2. Система связи по Шеннону, метрика Хемминга, МП-декодирование, теоремы Шеннона", "u": "oral/index.html#q2", "p": "Подготовка к устному экзамену", "k": "2. Система связи по Шеннону, метрика Хемминга, МП-декодирование, теоремы Шеннона частично Система связи с помехами по Шеннону. Блочный помехоустойчивый код. Метрика Хемминга и метод максимального правдоподобия. Геометрическая интерпретация корректирующих свойств кода. Энтропийная оценка \\(|B_t| \\le "}, {"t": "Короткий ответ (30–60 секунд)", "u": "oral/index.html#q2-short", "p": "Подготовка к устному экзамену", "k": "Сообщение длины k кодер превращает в кодовое слово длины n > k, добавляя избыточность. Канал прибавляет вектор ошибки: y = x + e. В двоичном симметричном канале с p < 1/2 вероятность P(y | x) = pᵈ(1 − p)ⁿ⁻ᵈ убывает с ростом расстояния Хемминга d(x, y), поэтому декодирование максимального правдоподоб"}, {"t": "Развёрнутый ответ — план", "u": "oral/index.html#q2-long", "p": "Подготовка к устному экзамену", "k": "Схема Шеннона: источник → кодер → канал (шум) → декодер → получатель; y = x + e. Теория Блочный код: кодирование Ψ: i ↦ x, длины k и n, скорость R = k/n, систематическое кодирование. ДСК(p): биты искажаются независимо с вероятностью p. Метрика Хемминга: определение, три аксиомы, вес, d(x, y) = ‖y − "}, {"t": "Уточняющие вопросы", "u": "oral/index.html#q2-followups", "p": "Подготовка к устному экзамену", "k": "Почему при p > 1/2 «ближайшее слово» уже не МП-декодер? Тогда p/(1 − p) > 1, и вероятность pᵈ(1 − p)ⁿ⁻ᵈ растёт с ростом d. Выгоднее инвертировать все принятые биты — получится канал с вероятностью ошибки 1 − p < 1/2. Почему код с расстоянием d обнаруживает d − 1 ошибку? Если ошибок от 1 до d − 1, то"}, {"t": "Связи с другими темами", "u": "oral/index.html#q2-links", "p": "Подготовка к устному экзамену", "k": "Объём шара → границы Хемминга и Варшамова — Гильберта (вопросы 5, 7). Асимптотика R ≳ 1 − H(δ) (вопросы 7 и 24) использует ту же энтропию H, что и теорема Шеннона. d = минимальный вес — для линейных кодов (вопрос 3). Пока не разобрано Энтропийная оценка \\(|B_t| \\le 2^{nH(t/n)}\\) и её следствие. В пр"}, {"t": "Вопрос 3. Групповые и линейные коды, матрицы G и H", "u": "oral/index.html#q3", "p": "Подготовка к устному экзамену", "k": "3. Групповые и линейные коды, матрицы G и H впереди: модуль 3 Групповые и линейные коды над конечным полем. Проверочная H и порождающая G матрицы линейного кода. Теорема о проверочной матрице линейного кода и его кодовом расстоянии d. Теорема о том, что кодовое расстояние линейного кода равно минима"}, {"t": "Вопрос 4. Систематический вид, синдромное декодирование, стандартное расположение", "u": "oral/index.html#q4", "p": "Подготовка к устному экзамену", "k": "4. Систематический вид, синдромное декодирование, стандартное расположение впереди: модуль 3 Приведение линейного кода к систематическому виду. Декодирование линейных кодов по синдрому. Полная и укороченная таблицы стандартного расположения кода. Декодирование линейного кода методом согласования. [2"}, {"t": "Вопрос 5. Границы сферической упаковки, совершенные коды, код Хемминга", "u": "oral/index.html#q5", "p": "Подготовка к устному экзамену", "k": "5. Границы сферической упаковки, совершенные коды, код Хемминга впереди: модуль 4 Границы сферической упаковки кода. Совершенные коды. Код Хемминга над полем \\(\\mathbb{F}_q\\), его свойства, декодирование. [7] с. 29–30, 33–36, 43–44, 50, 181; [9] с. 91–102; [15] гл. 16, 18. Отрепетировал ответ вслух "}, {"t": "Вопрос 6. Неравенства Синглтона и Грайсмера, МДР-коды", "u": "oral/index.html#q6", "p": "Подготовка к устному экзамену", "k": "6. Неравенства Синглтона и Грайсмера, МДР-коды впереди: модуль 4 Неравенство Синглтона для линейных кодов. Примеры МДР-кодов. Неравенство Грайсмера. [6] с. 595–598; [7] с. 43–44, 50; [9] с. 91–102; [11] с. 125–126, 132–135, 222–225. Отрепетировал ответ вслух Ответ отрепетирован"}, {"t": "Вопрос 7. Граница Варшамова — Гильберта и её асимптотика", "u": "oral/index.html#q7", "p": "Подготовка к устному экзамену", "k": "7. Граница Варшамова — Гильберта и её асимптотика впереди: модуль 4 Граница Варшамова — Гильберта. Сравнение с нижней границей сферической упаковки. Асимптотическая форма границы: существование таких семейств линейных (n, k, d)-кодов со скоростью R = k/n и относительным кодовым расстоянием δ = d/n, "}, {"t": "Вопрос 8. Коды Рида — Маллера, кодовое расстояние", "u": "oral/index.html#q8", "p": "Подготовка к устному экзамену", "k": "8. Коды Рида — Маллера, кодовое расстояние впереди: модуль 5 Коды Рида — Маллера. Теорема о кодовом расстоянии РМ-кода. [2] с. 76–81; [11] с. 135–161; [15] гл. 16, №№ 16.18, 9.49 (с. 472). Отрепетировал ответ вслух Ответ отрепетирован"}, {"t": "Вопрос 9. Мажоритарное декодирование кодов Рида — Маллера", "u": "oral/index.html#q9", "p": "Подготовка к устному экзамену", "k": "9. Мажоритарное декодирование кодов Рида — Маллера впереди: модуль 5 Коды Рида — Маллера. Мажоритарный алгоритм декодирования: проверочная сумма одночлена по грани и её свойства, нахождение АНФ (полинома Жегалкина) методом сумм. [2] с. 76–81; [11] с. 135–161; [15] гл. 16, № 16.20 (с. 510). Отрепетир"}, {"t": "Вопрос 10. Двоичное преобразование Мёбиуса", "u": "oral/index.html#q10", "p": "Подготовка к устному экзамену", "k": "10. Двоичное преобразование Мёбиуса впереди: модуль 5 Двоичное преобразование Мёбиуса. Основные свойства и сложность. Применение к РМ-кодам. [15] №№ 11.28, 9.9 (с. 467). Отрепетировал ответ вслух Ответ отрепетирован"}, {"t": "Вопрос 11. Кольца главных идеалов", "u": "oral/index.html#q11", "p": "Подготовка к устному экзамену", "k": "11. Кольца главных идеалов впереди: модуль 6 Кольцо главных идеалов. Кольца \\(\\mathbb{Z}\\), \\(\\mathbb{Z}_n\\), F[x] и F[x]/(f(x)) как кольца главных идеалов. [6, 16] Отрепетировал ответ вслух Ответ отрепетирован"}, {"t": "Вопрос 12. Циклические и полиномиальные коды, g(x) и h(x)", "u": "oral/index.html#q12", "p": "Подготовка к устному экзамену", "k": "12. Циклические и полиномиальные коды, g(x) и h(x) впереди: модули 7–8 Циклический код. Полиномиальный код. Критерий цикличности полиномиального кода. Порождающий g(x) и проверочный h(x) многочлены циклического кода. Циклический вид проверочной и порождающей матриц циклического кода. Теорема о том, "}, {"t": "Вопрос 13. Систематическое кодирование циклических кодов, двойственный код", "u": "oral/index.html#q13", "p": "Подготовка к устному экзамену", "k": "13. Систематическое кодирование циклических кодов, двойственный код впереди: модуль 8 Систематическое кодирование для циклических кодов. Двойственный код. Теорема о полиномиальности кода, двойственного к циклическому полиномиальному. [6] с. 601–609; [9] с. 232–243; [11] с. 168–186. Отрепетировал отв"}, {"t": "Вопрос 14. Примитивные и непримитивные циклические коды, корни", "u": "oral/index.html#q14", "p": "Подготовка к устному экзамену", "k": "14. Примитивные и непримитивные циклические коды, корни впереди: модуль 8 Примитивные и непримитивные циклические коды. Корни уравнения xⁿ − 1 = 0 как циклическая группа в расширении \\(\\mathbb{F}_{q^m}\\) поля коэффициентов \\(\\mathbb{F}_q\\). Задание примитивных и непримитивных циклических кодов их ко"}, {"t": "Вопрос 15. Порядок многочлена над конечным полем", "u": "oral/index.html#q15", "p": "Подготовка к устному экзамену", "k": "15. Порядок многочлена над конечным полем впереди: модуль 8 Порядок многочлена над конечным полем: определение и связь с циклическими кодами. Теорема о порядке произведения взаимно простых многочленов как следствие китайской теоремы об остатках. Теорема о том, что порядок неприводимого многочлена ра"}, {"t": "Вопрос 16. Пакеты ошибок, циклические коды Хемминга, коды Абрамсона и CRC", "u": "oral/index.html#q16", "p": "Подготовка к устному экзамену", "k": "16. Пакеты ошибок, циклические коды Хемминга, коды Абрамсона и CRC впереди: модуль 8 Обнаружение пакетов ошибок циклическими кодами. Двоичные циклические коды Хемминга, коды Абрамсона и коды CRC. Теорема о вероятности необнаружения пакета ошибок циклическим кодом. [2] с. 131–134; [3] с. 189–214; [6]"}, {"t": "Вопрос 17. Коды БЧХ, граница БЧХ, исправление двух ошибок", "u": "oral/index.html#q17", "p": "Подготовка к устному экзамену", "k": "17. Коды БЧХ, граница БЧХ, исправление двух ошибок впереди: модуль 9 Коды БЧХ. Граница Боуза — Чоудхури — Хоквингема d ⩾ dк для кодового расстояния d и конструктивного расстояния dк. Локатор ошибки кода БЧХ. Декодирование двоичных БЧХ-кодов, исправляющих две ошибки. [2] с. 134–136, 187–192; [6] с. 6"}, {"t": "Вопрос 18. Алгоритм Питерсона — Горенштейна — Цирлера", "u": "oral/index.html#q18", "p": "Подготовка к устному экзамену", "k": "18. Алгоритм Питерсона — Горенштейна — Цирлера впереди: модуль 9 Алгоритм Питерсона — Горенштейна — Цирлера декодирования кодов БЧХ над полем \\(\\mathbb{F}_q\\). Доказательство корректности и оценка сложности O(t³ + nt). Процедура Ченя. [2] с. 193–201; [6] с. 611–616; [9] с. 315–331; [11] с. 215–221; "}, {"t": "Вопрос 19. Ключевое уравнение Берлекемпа, метод Форни", "u": "oral/index.html#q19", "p": "Подготовка к устному экзамену", "k": "19. Ключевое уравнение Берлекемпа, метод Форни впереди: модуль 11 Многочлены локаторов и значений ошибок. Синдромный многочлен. Доказательство ключевого уравнения Берлекемпа \\(x^{2t}\\cdot\\Psi(x) + S(x)\\cdot\\Lambda(x) = \\Omega(x)\\) для декодирования кода БЧХ. Вычисление значений ошибок методом Форни."}, {"t": "Вопрос 20. Алгоритм Евклида и алгоритм Берлекемпа — Месси для БЧХ", "u": "oral/index.html#q20", "p": "Подготовка к устному экзамену", "k": "20. Алгоритм Евклида и алгоритм Берлекемпа — Месси для БЧХ впереди: модуль 11 Расширенный алгоритм Евклида, его основные свойства и квадратичная оценка сложности в кольце F[x]. Декодирование кодов БЧХ алгоритмом Евклида с порогом «min i : deg dᵢ(x) ⩽ t − 1» и алгоритмом Берлекемпа — Месси со сложнос"}, {"t": "Вопрос 21. Циклические коды Рида — Соломона", "u": "oral/index.html#q21", "p": "Подготовка к устному экзамену", "k": "21. Циклические коды Рида — Соломона впереди: модуль 11 Циклические коды Рида — Соломона. Теорема о совпадении кодового расстояния с конструктивным. Исправление RS–кодом пакетов ошибок над простым подполем. Декодирование циклического RS–кода: алгоритмы Питерсона — Горенштейна — Цирлера, Евклида, Бер"}, {"t": "Вопрос 22. Каскадные коды, ошибки и стирания", "u": "oral/index.html#q22", "p": "Подготовка к устному экзамену", "k": "22. Каскадные коды, ошибки и стирания впереди: модуль 12 Каскадные коды. Оценка кодового расстояния d каскадн ⩾ d внеш ·d внутр . Исправление любым каскадным кодом до t внеш ·t внутр + t внеш + t внутр ∼ d внеш ·d внутр /4 произвольных ошибок простой суперпозицией внешнего и внутреннего декодеров бе"}, {"t": "Вопрос 23. Коды Гоппы общего вида", "u": "oral/index.html#q23", "p": "Подготовка к устному экзамену", "k": "23. Коды Гоппы общего вида впереди: модуль 12 Коды Гоппы. Общий вид проверочной матрицы кода Гоппы, её связь с коэффициентами генераторного полинома g(x). Теорема d ⩾ 1 + deg g(x) о кодовом расстоянии кода Гоппы общего вида над полем \\(\\mathbb{F}_q\\). Ключевое уравнение для декодирования кода Гоппы "}, {"t": "Вопрос 24. Двоичные неприводимые коды Гоппы, система МакЭлиса", "u": "oral/index.html#q24", "p": "Подготовка к устному экзамену", "k": "24. Двоичные неприводимые коды Гоппы, система МакЭлиса впереди: модуль 12 Двоичные неприводимые коды Гоппы. Теорема d ⩾ 1 + 2t, где t = deg g(x), об оценке кодового расстояния в двоичном случае для свободного от квадратов g(x) и теорема о том, что в двоичном случае генераторный полином g²(x) даёт то"}, {"t": "Вопрос 25. Рекуррентные оценки сложности, алгоритм Карацубы", "u": "oral/index.html#q25", "p": "Подготовка к устному экзамену", "k": "25. Рекуррентные оценки сложности, алгоритм Карацубы впереди: модуль 10 Решение уравнения T(n) = aT(n/b) + cn для сложности T(n) некоторого рекуррентного алгоритма при постоянных a, b, c и n → ∞. Умножение многочленов алгоритмом Карацубы и кодирование циклического кода со сложностью O(n 1.585 ). [4]"}, {"t": "Вопрос 26. ДПФ и алгоритм Кули — Тьюки", "u": "oral/index.html#q26", "p": "Подготовка к устному экзамену", "k": "26. ДПФ и алгоритм Кули — Тьюки впереди: модуль 12 Дискретное преобразование Фурье (ДПФ) и обратное ДПФ. Их применение к арифметике многочленов — умножение, интерполяция. Алгоритм Кули — Тьюки для бинарного ДПФ со сложностью O(n log n), сеть «бабочка». [4] гл. 2; [5] гл. 30; [8] гл. 5; [19] § 8.2. П"}, {"t": "Вопрос 27. Быстрое деление многочленов с остатком", "u": "oral/index.html#q27", "p": "Подготовка к устному экзамену", "k": "27. Быстрое деление многочленов с остатком впереди: модуль 12 Деление многочлена на многочлен с остатком со сложностью, по порядку не превышающей сложности умножения и интерполяции полиномов. [19] § 9.1. Пробел в материалах В присланных презентациях этой темы нет. Источник — [19] § 9.1 (деление чере"}, {"t": "Модули", "u": "plan.html#modules", "p": "План обучения", "k": "1 Модуль 1. Арифметика по модулю и введение в коды Чтобы отмечать статусы, включите JavaScript."}, {"t": "После модуля 12", "u": "plan.html#after", "p": "План обучения", "k": "Оставшееся до экзамена время — повторение: пробный устный экзамен по билетам, вопросы «на ходу» и разбор слабых мест."}, {"t": "Перенос прогресса", "u": "plan.html#progress-io", "p": "План обучения", "k": "Сайт запоминает: статусы модулей, прочитанные блоки, решённые задачи, заметки к задачам, ответы и результаты тестов, отрепетированные вопросы и место, где вы остановились. Всё это хранится в браузере на этом устройстве и никуда не отправляется. Данные пропадут, если очистить данные сайта в настройка"}, {"t": "Блок 1.1. Арифметика по модулю", "u": "practice/m01.html#p11", "p": "Практика, модуль 1", "k": "Решено Задача 1 ★ разминка Вычислите: 23 mod 7; −8 mod 3; 100 mod 7; −1 mod 2; 0 mod 5. Заметки есть запись Решайте в тетради, а сюда запишите итоговый ответ или место, где застряли. Заметка хранится в этом браузере. Заметки к задаче 1 Подсказка"}, {"t": "Блок 1.2. Расстояние Хемминга и параметры кода", "u": "practice/m01.html#p12", "p": "Практика, модуль 1", "k": "Решено Задача 12 ★ разминка Найдите d( 1011010 , 0011101 ) и вес каждого вектора. Заметки есть запись Решайте в тетради, а сюда запишите итоговый ответ или место, где застряли. Заметка хранится в этом браузере. Заметки к задаче 12 Ответ"}, {"t": "Задачи из программы экзамена", "u": "practice/m01.html#pexam", "p": "Практика, модуль 1", "k": "Курс: программа экзамена 2025 года, раздел «Примеры экзаменационных вопросов и задач» Условия приведены дословно, в скобках — номер задачи в программе. Решено Задача 20 (программа, № 2) ★★★ сложная «Найти максимально возможную мощность двоичного кода длины n, обнаруживающего одну ошибку. Доказать, ч"}, {"t": "Модули", "u": "review/index.html#modules", "p": "Повторение", "k": "Модуль 1. Арифметика по модулю и введение в коды 26.10–01.11, вопросы программы: 2 Модуль 2. Линейная алгебра над конечным полем 02.11–08.11, база для следующих тем. Появится позже Модуль 3. Линейные коды 09.11–15.11, вопросы программы: 3, 4. Появится позже Модуль 4. Границы для кодов и коды Хемминг"}, {"t": "Конспект", "u": "review/m01.html#summary", "p": "Повторение, модуль 1", "k": ""}, {"t": "Блок 1.1. Арифметика по модулю", "u": "review/m01.html#sum-11", "p": "Повторение, модуль 1", "k": "a mod n — остаток от 0 до n − 1; у отрицательных чисел остаток тоже неотрицательный: −7 mod 5 = 3. a ≡ b (mod n) ⇔ n | (a − b). Остатки можно брать на любом шаге вычислений. −a = n − a. В ℤ₂ вычитание = сложение = XOR. Деление — умножение на обратный. a⁻¹ существует ⇔ НОД(a, n) = 1; находится перебо"}, {"t": "Блок 1.2. Расстояние и параметры кода", "u": "review/m01.html#sum-12", "p": "Повторение, модуль 1", "k": "Схема: i → кодер → x → канал → y = x + e → декодер. Скорость R = k/n. ДСК(p): P(y | x) = pᵈ(1 − p)ⁿ⁻ᵈ. При p < 1/2 МП-декодирование = ближайшее кодовое слово. Расстояние Хемминга — число различающихся разрядов, это метрика; \\(d(x, y) = \\|y - x\\|\\). \\(|S_r| = \\binom{n}{r}(q-1)^r\\); \\(|B_r|\\) — сумма "}, {"t": "Ключевые формулы", "u": "review/m01.html#formulas", "p": "Повторение, модуль 1", "k": "\\[ a = qn + r,\\quad 0 \\le r < n \\] \\[ b/a = b\\cdot a^{-1} \\] \\[ P(y\\mid x) = p^{d(x,y)}(1-p)^{\\,n-d(x,y)} \\] \\[ |B_r| = \\sum_{i=0}^{r}\\binom{n}{i}(q-1)^i \\] \\[ \\begin{aligned} t &= \\left\\lfloor\\tfrac{d-1}{2}\\right\\rfloor, \\\\ s &= d-1, \\\\ s' &= \\left\\lceil\\tfrac{d-1}{2}\\right\\rceil \\end{aligned} \\] \\"}, {"t": "Карточки", "u": "review/m01.html#cards", "p": "Повторение, модуль 1", "k": "Сначала ответьте вслух, потом переверните карточку: нажмите на неё или на кнопку «Показать ответ». Нажмите ещё раз, чтобы вернуться к вопросу. Перемешать карточки Вопрос Чему равно −11 mod 4? Ответ 1, потому что −11 = (−3)·4 + 1. Показать ответ"}, {"t": "Мини-тест", "u": "review/m01.html#quiz", "p": "Повторение, модуль 1", "k": "Выберите ответы и нажмите «Проверить». Выбранные ответы, последний и лучший результат сохраняются в этом браузере. «Сбросить» очищает ответы, лучший результат остаётся. 1. Чему равно −13 mod 5? 3 2 −3 8 2. Чему равен 4⁻¹ в ℤ₇? 2 4"}, {"t": "Контрольные вопросы", "u": "review/m01.html#control", "p": "Повторение, модуль 1", "k": "Почему коды строят над полями, а не над ℤ₆? Как найти обратный элемент алгоритмом Евклида? Покажите на 7 по модулю 26. Выведите формулу P(y | x) для ДСК и объясните, при чём здесь расстояние Хемминга. Докажите, что расстояние Хемминга — метрика. Объясните разницу между s и s′ на примере кода с d = 4"}, {"t": "Как читать пометки", "u": "sources.html#labels", "p": "Источники и условные обозначения", "k": "Курс: … — содержание взято из материалов курса: тем лекций, домашних заданий или программы экзамена. В пометке указано, откуда именно. Пояснение — дополнительное объяснение, пример или задача авторов сайта. Помогает понять материал, но в лекциях этого может не быть. Пробел в материалах — нужного сод"}, {"t": "На что опирается сайт", "u": "sources.html#materials", "p": "Источники и условные обозначения", "k": "Программа экзамена по курсу «Алгебраическая теория кодирования» для групп ИУ8-74, 75, осень 2025 года: 27 вопросов, список литературы и 97 примеров задач. Вопросы и задачи на сайте приводятся дословно. Презентации лекций этого учебного года — ссылки вида «лекция 2». Набор пока неполный: преподавател"}, {"t": "Известные пробелы", "u": "sources.html#gaps", "p": "Источники и условные обозначения", "k": "Вопрос 1 (строение конечных полей) — материал весеннего семестра, в презентациях осеннего его нет. Источники: [6] Лидл, Нидеррайтер и [16] Чашкин, Жуков (так советует лектор в замечаниях к программе). Вопрос 2 — энтропийной оценки объёма шара нет в презентации лекции 1. Источник: [15] Чашкин «Дискре"}, {"t": "Литература из программы экзамена", "u": "sources.html#literature", "p": "Источники и условные обозначения", "k": "Курс: программа экзамена, список литературы Номера в квадратных скобках у вопросов программы относятся к этому списку. Аршинов М. Н., Садовский Л. Е. Коды и математика (рассказы о кодировании). Библиотечка «Квант», вып. 30. — М.: Наука, 1983. Блейхут Р. Теория и практика кодов, контролирующих ошибки"}, {"t": "Технические детали", "u": "sources.html#tech", "p": "Источники и условные обозначения", "k": "Формулы отображаются библиотекой KaTeX (лицензия MIT), её файлы лежат в папке assets/vendor/katex . Шрифты Unbounded, Golos Text и JetBrains Mono (лицензия SIL Open Font License) подгружаются с Google Fonts. Если загрузка не удалась, используются системные шрифты — сайт работает так же. Прогресс хра"}, {"t": "1.1 Арифметика по модулю", "u": "theory/m01.html#b11", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Пояснение: база, которую курс считает известной Курс напрямую этого не объясняет, но пользуется этим с первой лекции. Строго и подробно — в книге Чашкина и Жукова «Элементы конечной алгебры», глава 2 «Целые числа» (в программе экзамена это источник [16])."}, {"t": "Зачем это нужно", "u": "theory/m01.html#why", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "В теории кодирования символы сообщения — не обычные числа, а элементы конечного набора, например {0, 1} или {0, 1, 2}. Складывать и умножать их нужно так, чтобы результат не выходил за пределы набора. Это и делает арифметика по модулю: числа «ходят по кругу», как стрелки часов. Пример из лекции 1 «В"}, {"t": "Остатки и сравнения", "u": "theory/m01.html#remainder", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Определение: деление с остатком Для целого a и натурального n существуют единственные целые q и r такие, что \\[ a = q\\cdot n + r, \\quad 0 \\le r < n. \\] Число r называется остатком и обозначается a mod n . 17 mod 5 = 2, потому что 17 = 3·5 + 2. −7 mod 5 = 3 , потому что −7 = (−2)·5 + 3. Не −2: остато"}, {"t": "Сложение, вычитание, умножение", "u": "theory/m01.html#ops", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Главное правило: считайте как обычно, потом берите остаток. Остаток можно брать и на любом промежуточном шаге — ответ не изменится, а числа не будут расти. Пример: 23·34 mod 5. Честно: 782 mod 5 = 2. Быстро: 23 ≡ 3, 34 ≡ 4, 3·4 = 12 ≡ 2. Ответ тот же. Вычитание. Противоположный элемент −a — это n − "}, {"t": "Деление и обратный элемент", "u": "theory/m01.html#inverse", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Деление по модулю — это умножение на обратный элемент . Обычные дроби не работают: в \\(\\mathbb{Z}_5\\) нет числа «0,75». Определение: обратный элемент Обратный к a — такое число \\(a^{-1}\\), что \\(a\\cdot a^{-1} \\equiv 1 \\pmod n\\). Тогда \\(b / a = b\\cdot a^{-1}\\). a 1 2 3 4 a⁻¹ в \\(\\mathbb{Z}_5\\)"}, {"t": "Алгоритм Евклида: как найти обратный", "u": "theory/m01.html#euclid", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Для маленьких n (2, 3, 5, 7) обратный проще найти перебором. Для больших нужен расширенный алгоритм Евклида . Это важная тема, а не проходная: тот же алгоритм, только для многочленов, декодирует коды БЧХ, Рида — Соломона и Гоппы (вопросы программы 20 и 23). Идея. НОД(a, b) = НОД(b, a mod b): общие д"}, {"t": "Уравнения и векторы", "u": "theory/m01.html#vectors", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Линейное уравнение a·x + b = c в поле \\(\\mathbb{F}_p\\) решается как в школе: x = (c − b)·a⁻¹, и при a ≠ 0 решение ровно одно. Пример в \\(\\mathbb{Z}_5\\): 3x + 4 = 1 ⇒ 3x = −3 ≡ 2 ⇒ x = 2·3⁻¹ = 2·2 = 4. Проверка: 3·4 + 4 = 16 ≡ 1. В \\(\\mathbb{Z}_n\\) с составным n уравнения ведут себя странно: решений "}, {"t": "Заглядываем вперёд: степени и примитивный элемент", "u": "theory/m01.html#powers", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Пояснение: задел на модуль 7 (вопрос 1 программы) k 1 2 3 4 5 6 3ᵏ mod 7 3 2 6 4 5 1 2ᵏ mod 7 2 4 1 2 4 1 Степени тройки пробегают все ненулевые элементы \\(\\mathbb{F}_7\\) — такой элемент называется примитивным . Степени двойки зацикливаются уже после трёх шагов: число 3 —"}, {"t": "1.2 Расстояние Хемминга и параметры кода", "u": "theory/m01.html#b12", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Курс: лекция 1 «Введение. Основные понятия помехоустойчивого кодирования»; программа, вопрос 2"}, {"t": "Система связи с помехами", "u": "theory/m01.html#channel", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "По Шеннону система связи устроена так: источник выдаёт сообщение, кодер добавляет к нему избыточность, канал вносит помехи, декодер по искажённому слову восстанавливает сообщение, приёмник его получает. сообщение i кодер кодовое слово x канал: помеха +e принято y = x + e декодер оценка x̂ , затем"}, {"t": "Декодирование максимального правдоподобия", "u": "theory/m01.html#ml", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Получили y. Какое кодовое слово отправляли? Метод максимального правдоподобия (МП) выбирает x ∈ C, для которого вероятность P(y | x) получить именно y наибольшая. Утверждение: в ДСК(p) при p < 1/2 МП = «ближайшее кодовое слово» Если x и y различаются в d разрядах, то \\[ \\begin{aligned} P(y \\mid x) &"}, {"t": "Расстояние Хемминга, вес, метрика", "u": "theory/m01.html#hamming", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Определения Расстояние Хемминга d(α, β) между векторами α, β ∈ \\(\\mathbb{F}_q^n\\) — число разрядов, в которых они различаются. Вес ‖α‖ — число ненулевых координат вектора α. Наборы, различающиеся в одном разряде, называются соседними , во всех разрядах — противоположными . Пример: d( 10"}, {"t": "Шары, сферы, булев куб", "u": "theory/m01.html#balls", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Шар и сфера \\(B_r(a) = \\{ b : d(a, b) \\le r \\}\\) — шар радиуса r с центром a. \\(S_r(a) = \\{ b : d(a, b) = r \\}\\) — сфера радиуса r. Сколько векторов на сфере радиуса r? Выбираем, какие r разрядов изменить (\\(\\binom{n}{r}\\) способов), и в каждом — на какой из q − 1 других символов: \\[ \\begin{aligned}"}, {"t": "Кодовое расстояние и числа t, s, s′", "u": "theory/m01.html#codedist", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Определение: кодовое расстояние Любое подмножество C ⊆ \\(\\mathbb{F}_q^n\\) называется кодом длины n. Его кодовое (минимальное) расстояние \\[ d(C) = \\min_{a,\\,b\\,\\in\\, C,\\; a \\ne b} d(a, b). \\] Определения: исправление и обнаружение Код обнаруживает s ошибок , если при искажении любого кодового слова "}, {"t": "Пример: код с повторением", "u": "theory/m01.html#repetition", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Курс: пример из лекции 1 «Введение» Кодируем 0 → 000, 1 → 111 и декодируем «голосованием»: принимается тот символ, которого в слове больше (100 → 0, 101 → 1). Код ошибается, если испорчены 2 или 3 бита из трёх: \\[ P_{\\text{ош}} = \\binom{3}{2}p^2(1-p) + p^3 = 3p^2 - 2p^3. \\] При p = 1/100 получаем \\("}, {"t": "Теоремы Шеннона (без доказательства)", "u": "theory/m01.html#shannon", "p": "Теория, модуль 1: арифметика по модулю и введение в коды", "k": "Энтропия и пропускная способность ДСК(p) \\[ \\begin{aligned} H(p) &= -p\\log_2 p - (1-p)\\log_2(1-p), \\\\ C(p) &= 1 - H(p). \\end{aligned} \\] H(p) определена на [0, 1] (в концах — по непрерывности), симметрична относительно 1/2 и выпукла вверх; H(1/2) = 1. Прямая теорема Шеннона (1948) Для любых p ≠ 1/2,"}, {"t": "Калькулятор по модулю", "u": "tools.html#mod-h", "p": "Тренажёры", "k": "Сложение, вычитание, умножение, деление, степень и обратный элемент. Для деления и обратного показывается таблица расширенного алгоритма Евклида — как в теории . a Действие a + b a − b a · b a / b a в степени b обратный к a"}, {"t": "Расстояние Хемминга и вес", "u": "tools.html#dist-h", "p": "Тренажёры", "k": "Введите два вектора одной длины цифрами без пробелов, например 1021. Тренажёр покажет различающиеся разряды, веса и вектор ошибки e = y − x. Поле 𝔽₂ 𝔽₃ 𝔽₅ 𝔽₇ x (отправлено) y (принято) Сравнить Здесь появится результат. Пример заполнен из лекции 1 «Введение»."}, {"t": "Параметры кода: d, t, s, s′", "u": "tools.html#code-h", "p": "Тренажёры", "k": "Введите все кодовые слова через пробел, запятую или с новой строки. Тренажёр переберёт все пары и найдёт кодовое расстояние. Поле 𝔽₂ 𝔽₃ 𝔽₅ 𝔽₇ Кодовые слова 00000 11100 00111 11011 Найти d Здесь появится результат. Пример — код из"}, {"t": "Код Хемминга (7, 4)", "u": "tools.html#hm-h", "p": "Тренажёры", "k": "Интерактивная демонстрация — на главной странице . Подробно коды Хемминга разберём в модуле 4."}];
